methods.Service/ShareService.php::list:
function list(int $pollOrPollGroupId, string $purpose = 'poll'): array {
		try {
			if ($purpose === 'poll') {
				$poll = $this->pollMapper->get($pollOrPollGroupId)
					->request(Poll::PERMISSION_POLL_EDIT);
				$this->shares = $this->shareMapper->findByPoll($pollOrPollGroupId, $poll->getPollGroups());
			} else {
				$this->pollGroupMapper->find($pollOrPollGroupId);
				$this->shares = $this->shareMapper->findByPollGroup($pollOrPollGroupId);
			}
		} catch (ForbiddenException $e) {
			return [];
		} catch (DoesNotExistException $e) {
			return [];
		}
		$this->sortByCategory();
		return $this->shares;
	}

methods.Service/ShareService.php::sortByCategory:
function sortByCategory(): void {
		$sortedShares = [];
		foreach (Share::TYPE_SORT_ARRAY as $shareType) {
			$filteredShares = array_filter($this->shares, function ($share) use ($shareType) {
				return $share->getType() === $shareType;
			});
			$sortedShares = array_merge($sortedShares, $filteredShares);
		}
		$this->shares = $sortedShares;
	}

methods.Service/ShareService.php::validateShareT:
function validateShareType(): void {

		$valid = match ($this->share->getType()) {
			// Public shares are always allowed
			Share::TYPE_PUBLIC => true,

			// External shares are only allowed, if the user is not logged in
			Share::TYPE_CONTACT, Share::TYPE_EMAIL, Share::TYPE_EXTERNAL
				=> !$this->userSession->getIsLoggedIn(),

			// User and Admin shares are only allowed, if the user is logged in and the share belongs to the current user
			Share::TYPE_USER, Share::TYPE_ADMIN
				=> $this->userSession->getIsLoggedIn() && $this->share->getUserId() === $this->userSession->getCurrentUserId(),

			// Note: $this->share->getUserId() is actually the group name in case of Share::TYPE_GROUP
			Share::TYPE_GROUP => $this->userSession->getIsLoggedIn() && $this->userSession->getCurrentUser()->getIsInGroup($this->share->getUserId()),

			default => throw new ForbiddenException("Invalid share type {$this->share->getType()}"),
		}

methods.Db/EntityWithUser.php::getEntityAnonymiz:
function getEntityAnonymization(): bool {
		if ($this->getCurrentUserIsEntityUser()) {
			// if the current user is the owner of the entity, don't anonymize the entity
			return false;
		}

		if ($this->getAnonymized() < 0) {
			// the poll is anonymized and locked, anonymize the entity
			return true;
		}

		$userSession = Container::queryClass(UserSession::class);
		if ($this->getPollOwnerId() === $userSession->getCurrentUserId()) {
			// if the current user is the poll owner, don't anonymize the entity
			return false;
		}

		if ($this->getShareType() === Share::TYPE_ADMIN) {
			// if the current user is a delegated admin, don't anonymize the entity
			return false;
		}

		if ($this->getAnonymized() > 0) {
			// if the current user is not the poll owner, anonymize the entity
			return true;
		}

		// the poll is not anonymized
		if ($this->getPollShowResults() === Poll::SHOW_RESULTS_NEVER
			|| ($this->getPollShowResults() === Poll::SHOW_RESULTS_CLOSED
				&& !$this->getPollExpire() > time())) {

			// Do not anonymize the poll owner
			return !($this instanceof Poll);
		}

		// in all other cases, don't anonymize the entity
		return false;
	}

