	}

methods.Db/PollMapper.php::buildQuery:
function buildQuery(bool $detailed = true): IQueryBuilder {
		$qb = $this->db->getQueryBuilder();

		$qb->select(self::TABLE . '.*')
			->from($this->getTableName(), self::TABLE)
			->groupBy(self::TABLE . '.id');

		$currentUserId = $this->userSession->getCurrentUserId();
		$currentUserParam = $qb->createNamedParameter($currentUserId, IQueryBuilder::PARAM_STR);
		$pollGroupsAlias = 'poll_groups';

		$this->subQueryMaxDate($qb, self::TABLE);

		$this->joinUserRole($qb, self::TABLE, $currentUserParam);
		$this->joinGroupShares($qb, self::TABLE);
		$this->joinPollGroups($qb, self::TABLE, $pollGroupsAlias);
		$this->joinPollGroupShares($qb, $pollGroupsAlias, $currentUserParam, $pollGroupsAlias);
		$this->joinParticipantsCount($qb, self::TABLE);

		$this->subQueryVotesCount($qb, self::TABLE, $currentUserParam);

		if ($detailed) {
			// Is not relevant for the polls collection
			$this->subQueryVotesCount($qb, self::TABLE, $currentUserParam, Vote::VOTE_YES);
			$this->subQueryVotesCount($qb, self::TABLE, $currentUserParam, Vote::VOTE_NO);
			$this->subQueryVotesCount($qb, self::TABLE, $currentUserParam, Vote::VOTE_EVENTUALLY);
			$this->subQueryOrphanedVotesCount($qb, self::TABLE, $currentUserParam);
		}

		return $qb;
	}

methods.Db/Poll.php::getAllowAccessPoll:
function getAllowAccessPoll(): bool {
		// edit rights include access to poll
		if ($this->getAllowEditPoll()) {
			return true;
		}

		// No further access to poll, if it is deleted
		if ($this->getDeleted()) {
			return false;
		}

		// grant access if poll poll is an open poll (for logged in users)
		if ($this->getIsOpenPoll() && $this->userSession->getIsLoggedIn()) {
			return true;
		}

		// grant access if user is involved in poll in any way
		if ($this->getIsInvolved()) {
			return true;
		}

		$share = $this->userSession->getShare();
		// return check result of an existing valid share for this user
		return boolval($share->getId() && $share->getPollId() === $this->getId());
	}

methods.Db/Poll.php::getAllowEditPoll:
function getAllowEditPoll(): bool {
		// Console has god mode
		if (defined('OC_CONSOLE')) {
			return true;
		}

		// owner is always allowed to edit the poll configuration
		if ($this->getIsPollOwner()) {
			return true;
		}

		// user has delegated owner rights
		if ($this->getIsDelegatedAdmin()) {
			return true;
		}

		// deny edit rights in all other cases
		return false;
	}

