function list(int $pollId): array {
		$this->getPoll($pollId)
			->request(Poll::PERMISSION_POLL_ACCESS);

		try {
			$this->options = $this->optionMapper->findByPoll($pollId, !$this->poll->getIsAllowed(Poll::PERMISSION_POLL_RESULTS_VIEW));
			$this->filterBookedUp();

		} catch (DoesNotExistException $e) {
			$this->options = [];
		}

		return array_values($this->options);
	}

methods.Service/OptionService.php::filterBookedU:
function filterBookedUp() {
		if (!$this->poll->getHideBookedUp() || $this->poll->getIsAllowed(Poll::PERMISSION_POLL_EDIT)) {
			return;
		}

		$this->options = array_filter($this->options, function ($option) {
			return (!$option->getIsLockedByOptionLimit());
		});
	}

methods.Db/Option.php::getIsLocked:
function getIsLocked(): bool {
		return $this->getDeleted()
			|| ($this->getUserVoteAnswer() !== Vote::VOTE_YES
			&& $this->getUserVoteAnswer() !== Vote::VOTE_EVENTUALLY
			&& ($this->getIsLockedByOptionLimit() || $this->getIsLockedByVotesLimit()));
	}
